  "id": "Kang2025",
  "type": "Research Article",
  "year": 2025,
  "title": "Towards hormone health: An autoethnography of long-term holistic tracking to manage PCOS",
  "authors": [
   "Daye Kang",
   "Jingjin Li",
   "Gilly Leshed",
   "Jeffrey M. Rzeszotarski",
   "Xi Lu"
  ],
  "venueShort": "CHI '25",
  "venue": "Proceedings of the 2025 CHI Conference on Human Factors in Computing Systems",
  "detail": "20 pages",
  "apa": "Kang, D., Li, J., Leshed, G., Rzeszotarski, J. M., & Lu, X. (2025). Towards hormone health: An autoethnography of long-term holistic tracking to manage PCOS. In *Proceedings of the 2025 CHI Conference on Human Factors in Computing Systems*. ACM. https://doi.org/10.1145/3706598.3713619",
  "doi": "10.1145/3706598.3713619",
  "license": "ACM",
